// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

interface IERC8217 {
    error UnknownAgent(uint256 agentId);

    /// @dev **APPEND ONLY. NEVER RENUMBER, REORDER, OR REMOVE A MEMBER.** The `uint8` of this enum
    /// sits in the preimage of every binding hash, so renumbering silently re-keys every identity
    /// claimed under it and nothing on chain records the old value. Values 0-4 name a token within a
    /// contract; the three account standards name an address itself and pin `tokenId` to 0. Per
    /// standard authority rules are documented on `AdapterImplementation._hasBindingControl`.
    enum Standard {
        ERC721,
        ERC1155,
        ERC6909,
        ERC1155F,
        ERC6909F,
        ACCOUNT,
        CONTRACT_OWNABLE,
        CONTRACT_ADMIN
    }

    struct Binding {
        Standard standard;
        address boundAddress;
        uint256 tokenId;
    }

    event AgentBound(
        uint256 indexed agentId,
        Standard indexed standard,
        address indexed boundAddress,
        uint256 tokenId,
        address registeredBy
    );

    /// @notice The stored `Binding` for `agentId`, reverting `UnknownAgent` when the id carries none.
    /// @dev ERC-8217 mandates this function on this interface.
    function bindingOf(uint256 agentId) external view returns (Binding memory);

    /// @notice The globally unique identifier of the bound object, called the Universal Binding
    /// Identifier (UBID) in the ERC, derived as
    /// `keccak256(abi.encode(bindingContractInteroperableAddress, standard, boundAddress, tokenId))`.
    /// A binding is immutable, so it holds for the life of the identity. Reverts `UnknownAgent` when
    /// the id carries no binding.
    /// @dev ERC-8217 mandates this function on this interface.
    function bindingHashOf(uint256 agentId) external view returns (bytes32);
}

src/interfaces/IERC8004AdapterAttestatio.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

/// @notice Emit-only attestations to counterfactual identities. An attestation is a public
/// statement about a UBID, recorded in the event log by the account
/// that makes it. The caller is always the attester, so the meaning of every statement rests on
/// who sent the transaction. The contract records the statement and derives its identifier, and
/// interpretation belongs to indexers: they resolve targets against counterfactual claims, apply
/// the published projection rules in log order, and enforce each type's payload and submitter
/// rules at read time. The full type registry, the projection rules, and the verification rules
/// live in `docs/specs/attestation-type-registry-v1.md`.
interface IERC8004AdapterAttestation {
    /// @dev **APPEND ONLY. NEVER RENUMBER, NEVER REORDER, NEVER REMOVE A MEMBER.** These numbers are
    /// identity-critical for the same reason `IERC8217.Standard`'s are: the `uint8` of
    /// this enum sits in the preimage of every `attestationId`, so renumbering a member re-keys every
    /// attestation ever emitted under it, and every revocation that names one. Nothing on chain
    /// records the old value, so that is unrecoverable. Add new types at the end.
    ///
    /// `UNSPECIFIED` holds zero and is never a real type. Solidity enums start at zero, so without it
    /// the first real type would be the value a default-initialized variable carries, which is
    /// exactly what `AttestationTypeZero` exists to reject.
    ///
    /// The set is closed: admitting a sixth type is an upgrade. That is deliberate. The upside is
    /// that the ABI decoder rejects an out-of-range value before any contract code runs, so a garbage
    /// type costs nothing to refuse and can never reach the log.
    enum AttestationType {
        /// Reserved sentinel. Never a real type; rejected by `AttestationTypeZero`.
        UNSPECIFIED,
        /// The attester is an additional account of the agent. State projection, empty payload.
        CONFIRM_ACCOUNT,
        /// Endorsement toggle. State projection. One byte, `1` stars and `0` unstars. Aggregates by
        /// counting the attesters whose live value is `1`.
        STAR,
        /// Quality rating. State projection. One byte, `0` to `100`, on the ERC-8004 `starred`
        /// scale. Aggregates by averaging each attester's live value.
        RATING,
        /// Written review. Stream projection. Payload is the UTF-8 text, at least one byte.
        REVIEW,
        /// Record of one dealing. Stream projection. Payload is at least 33 bytes: byte 0 is the
        /// outcome score, `0` to `100`; bytes 1 to 32 are a reference identifying the dealing,
        /// typically a transaction hash, zero when absent; bytes 33 onward are optional UTF-8 text.
        INTERACTION
    }

    /// @notice Thrown when `attestationType` is `UNSPECIFIED`. Zero is reserved as the
    /// uninitialized-input sentinel so a forgotten field fails instead of recording a statement of no
    /// stated type.
    error AttestationTypeZero();
    /// @notice Thrown when `ubid` is zero on an attest path. Zero is reserved as the
    /// uninitialized-input sentinel so a forgotten target fails instead of attaching a statement
    /// to the zero identity. Every nonzero value is accepted, including one that matches no claim
    /// yet: attesting ahead of an identity's first counterfactual claim is a supported use.
    error AttestationTargetZero();

    /// @notice A statement was recorded. `attester` is the account that made it and is the caller
    /// of the recording transaction. `attestationId` is the statement's identifier, derived as
    /// `keccak256(abi.encode(interoperableAddress(adapter), attester, ubid, attestationType,
    /// block.number, variant, data))` with `attestationType` encoded as the enum's `uint8`, and is
    /// recomputable from this event plus its log context. The three indexed fields serve the three
    /// canonical query axes: reverse by attester, forward by target, and filter by type.
    event Attested(
        address indexed attester,
        AttestationType indexed attestationType,
        bytes32 indexed ubid,
        bytes32 attestationId,
        bytes32 variant,
        bytes data
    );

    /// @notice A revocation was recorded for `attestationId` by `revoker`, the caller. The
    /// identifier is indexed because it is the join key back to the `Attested` event. A revocation
    /// changes projected state exactly when `revoker` equals the attester of the statement bearing
    /// this identifier, which indexers verify against the log, since the contract stores nothing.
    event AttestationRevoked(bytes32 indexed attestationId, address indexed revoker);

    /// @notice Record a statement of `attestationType` about the counterfactual identity `ubid`,
    /// with `data` carrying the type's payload. The caller is the attester. `variant` separates
    /// otherwise byte-identical statements made within one block and is zero when a single
    /// statement per block is enough; across blocks, `block.number` in the identifier already
    /// keeps identical statements distinct. Emits `Attested` with the derived identifier. Reverts
    /// `AttestationTypeZero` or `AttestationTargetZero` on an `UNSPECIFIED` type or a zero target.
    /// A value outside the enum never reaches this function: the ABI decoder rejects it first.
    function attest(AttestationType attestationType, bytes32 ubid, bytes32 variant, bytes calldata data) external;

    /// @notice Record that the caller is an additional account of the agent `ubid` identifies.
    /// Equivalent to `attest(AttestationType.CONFIRM_ACCOUNT, ubid, 0, "")`. This is the reciprocal half of the
    /// ERC-8048 `account` metadata list: the confirmation verifies while the agent's current
    /// forward metadata names the caller, checked live by the reader. Reverts
    /// `AttestationTargetZero` on a zero target.
    function confirmAdditionalAccount(bytes32 ubid) external;

    /// @notice Record a revocation of the statement identified by `attestationId`. The caller is
    /// the revoker. The revocation withdraws the statement when the caller is its attester, and is
    /// recorded as inert history otherwise, projection rule four. Accepts every identifier,
    /// including one never attested and including zero: revoking a statement that was never made
    /// is a recorded no-op under projection rule three, so the identifier is passed through
    /// unchecked. Emits `AttestationRevoked`.
    function revoke(bytes32 attestationId) external;
}

src/interfaces/IERC8004AdapterCounterfac.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {IERC8217} from "./IERC8217.sol";
import {IERC8004IdentityRegistry} from "./IERC8004IdentityRegistry.sol";

/// @notice Declares the counterfactual functions and events of `AdapterImplementation`, an alternative to full
/// ERC-8004 registration that records each call in the event log rather than the registry, so a claim
/// costs a log instead of a registration.
interface IERC8004AdapterCounterfactual {
    /// @notice Convenience helper that derives a UBID from user supplied arguments.
    function hashBinding(IERC8217.Standard standard, address boundAddress, uint256 tokenId)
        external
        view
        returns (bytes32);

    /// @notice Claims an identity for a bound address without registering it, returning the UBID claimed.
    function counterfactualRegister(
        IERC8217.Standard standard,
        address boundAddress,
        uint256 tokenId,
        string calldata agentURI,
        IERC8004IdentityRegistry.MetadataEntry[] memory metadata
    ) external returns (bytes32 bindingHash);

    /// @notice Overload of `counterfactualRegister` taking no metadata entries.
    function counterfactualRegister(
        IERC8217.Standard standard,
        address boundAddress,
        uint256 tokenId,
        string calldata agentURI
    ) external returns (bytes32 bindingHash);

    /// @notice Updates the agent URI for a counterfactual identity.
    function counterfactualSetAgentURI(
        IERC8217.Standard standard,
        address boundAddress,
        uint256 tokenId,
        string calldata newURI
    ) external returns (bytes32 bindingHash);

    /// @notice Records one metadata entry for a counterfactual identity.
    function counterfactualSetMetadata(
        IERC8217.Standard standard,
        address boundAddress,
        uint256 tokenId,
        string calldata metadataKey,
        bytes calldata metadataValue
    ) external returns (bytes32 bindingHash);

    /// @notice Records several metadata entries for a counterfactual identity, all on one UBID, in one event.
    function counterfactualSetMetadataBatch(
        IERC8217.Standard standard,
        address boundAddress,
        uint256 tokenId,
        IERC8004IdentityRegistry.MetadataEntry[] calldata metadata
    ) external returns (bytes32 bindingHash);

    /// @notice Assigns the agent wallet for a counterfactual identity. No signature is required, because
    /// no ERC-8004 wallet binding is created and the event is only an off-chain claim.
    function counterfactualSetAgentWallet(
        IERC8217.Standard standard,
        address boundAddress,
        uint256 tokenId,
        address newWallet
    ) external returns (bytes32 bindingHash);

    /// @notice Names the caller as this identity's agent wallet and points the caller's wallet back at
    /// it, in one call. The wallet is always `msg.sender`, which supplies consent for the reverse half,
    /// so no signature is needed and any existing designation on the caller is overwritten.
    function counterfactualSetAgentWalletAndUBID(IERC8217.Standard standard, address boundAddress, uint256 tokenId)
        external
        returns (bytes32 bindingHash);

    /// @notice Clears the agent wallet on a counterfactual identity, leaving other fields alone.
    function counterfactualUnsetAgentWallet(IERC8217.Standard standard, address boundAddress, uint256 tokenId)
        external
        returns (bytes32 bindingHash);

    // -----------------------------------------------------------------
    //  Wallet UBID: the reverse claim, wallet to UBID
    // -----------------------------------------------------------------
    //
    // The UBID a wallet picks for itself, emit-only like the rest of this interface. The adapter
    // derives the value from the coordinates rather than taking it from the caller, but the
    // designation itself is only a self-assertion, so a consumer should confirm the identity points
    // back at the wallet before trusting it. Projecting in log order, the latest `WalletUBIDSet` per
    // account wins and `WalletUBIDCleared` unsets. Only the wallet itself may emit either claim:
    // the account and actor are always `msg.sender`. Smart wallets execute these calls through
    // their own authorization policy; the adapter does not probe owners or admins on their behalf.
    // A wallet-to-agent-id surface sat here until `0.0.17` and should not be
    // re-added; see CHANGELOG 0.0.17 Removed for why.

    /// @notice Records the caller's own wallet UBID. Nothing here checks that the caller holds the token,
    /// so a consumer should confirm the identity points back at this wallet before trusting the claim.
    function setWalletUBID(IERC8217.Standard standard, address boundAddress, uint256 tokenId)
        external
        returns (bytes32 bindingHash);

    /// @notice Clears the caller's own wallet UBID. Calling it more than once, or with nothing set, is
    /// harmless and still emits `WalletUBIDCleared`, since the log is the record.
    function clearWalletUBID() external;

    /// @notice Announces a counterfactual identity claim. Consumers key on `ubid`, never on
    /// `(boundAddress, tokenId)`, which does not name a standard. Later events supersede earlier ones
    /// per UBID in log order, highest block then highest log index.
    event CounterfactualAgentRegistered(
        bytes32 indexed ubid,
        address indexed boundAddress,
        uint256 indexed tokenId,
        IERC8217.Standard standard,
        string agentURI,
        IERC8004IdentityRegistry.MetadataEntry[] metadata,
        address emitter
    );

    /// @notice Updates the agent URI for a counterfactual identity.
    event CounterfactualAgentURISet(
        bytes32 indexed ubid,
        address indexed boundAddress,
        uint256 indexed tokenId,
        IERC8217.Standard standard,
        string newURI,
        address emitter
    );

    /// @notice Records one metadata entry for a counterfactual identity.
    event CounterfactualMetadataSet(
        bytes32 indexed ubid,
        address indexed boundAddress,
        uint256 indexed tokenId,
        IERC8217.Standard standard,
        string metadataKey,
        bytes metadataValue,
        address emitter
    );

    /// @notice Records several metadata entries for a counterfactual identity in one event.
    event CounterfactualMetadataBatchSet(
        bytes32 indexed ubid,
        address indexed boundAddress,
        uint256 indexed tokenId,
        IERC8217.Standard standard,
        IERC8004IdentityRegistry.MetadataEntry[] metadata,
        address emitter
    );

    /// @notice Assigns the agent wallet for a counterfactual identity. No signature is required.
    event CounterfactualAgentWalletSet(
        bytes32 indexed ubid,
        address indexed boundAddress,
        uint256 indexed tokenId,
        IERC8217.Standard standard,
        address newWallet,
        address emitter
    );

    /// @notice Clears the agent wallet on a counterfactual identity.
    event CounterfactualAgentWalletUnset(
        bytes32 indexed ubid,
        address indexed boundAddress,
        uint256 indexed tokenId,
        IERC8217.Standard standard,
        address emitter
    );

    /// @notice Records a wallet's own UBID designation. `standard` is carried so a reader can recompute
    /// the UBID from this one log line.
    event WalletUBIDSet(
        address indexed account,
        bytes32 indexed ubid,
        address boundAddress,
        uint256 tokenId,
        IERC8217.Standard standard,
        address indexed setBy
    );

    /// @notice Clears a wallet's own UBID designation.
    event WalletUBIDCleared(address indexed account, address indexed clearedBy);
}

src/interfaces/IInteroperableAddressView.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

/// @notice Read-only ERC-7930 encoding for the chain this contract is deployed on. Neither function
/// carries any binding, counterfactual or attestation meaning: they expose the envelope that other
/// surfaces embed in the identifiers they derive. They are separated so a consumer that needs the
/// encoding does not have to import an identity interface, and so an identity interface does not
/// have to carry an encoding concern.
///
/// The values are what every identifier this contract issues is built on, so they are effectively
/// frozen. `interoperableAddress(address(this))` is the first component of every UBID and of
/// every attestation identifier, which means a change to this encoding
/// re-keys both. The production implementation delegates to OpenZeppelin's `draft-` prefixed
/// `InteroperableAddress`, which owes no encoding stability across releases; the exact bytes are
/// pinned against three independent oracles in `test/Adapter8004.erc7930-frozen.t.sol`.
interface IInteroperableAddressView {
    /// @notice Local ERC-7930 v1 Chain Identifier using CAIP-350 `eip155`: version 1, ChainType 0,
    /// shortest non-empty big-endian `block.chainid`, and zero AddressLength.
    function chainIdentifier() external view returns (bytes memory);

    /// @notice Full local ERC-7930 v1 Interoperable Address for an EVM account: the same chain
    /// envelope as `chainIdentifier()`, followed by AddressLength 20 and the raw address bytes.
    function interoperableAddress(address account) external view returns (bytes memory);
}

src/interfaces/IERC8004AdapterRegistrati.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {IERC8217} from "./IERC8217.sol";
import {IERC8004IdentityRegistry} from "./IERC8004IdentityRegistry.sol";

/// @notice Agent creation entry point for `AdapterImplementation`: registers through an ERC-8004 registry
/// after proving authority over an external bound token. Authority is ordinary current control or,
/// for ERC-721/ERC-1155F/ERC-6909F only, the directly calling token contract while `ownerOf(tokenId)`
/// reports no current owner. That temporary collection path closes after mint. Plain ERC-1155 and
/// ERC-6909 remain positive-balance controlled. Differs from `IERC8004IdentityRegistry.register`,
/// which mints an identity directly from URI + metadata only.
interface IERC8004AdapterRegistration {
    /// @notice Mint a new ERC-8004 identity owned by the adapter and bind it permanently to the given
    /// external token. The caller must hold authority over that token under the rules above. The
    /// binding is immutable once set, so a token pair and standard identify the same agent for the
    /// life of the identity, and control follows the token rather than the registering address. The
    /// adapter writes its own `agent-binding` record, so `metadata` may not contain that key and a
    /// caller-supplied entry for it reverts `ReservedMetadataKey`. Every other key is accepted.
    /// Emits `AgentBound` and returns the new `agentId`.
    function register(
        IERC8217.Standard standard,
        address boundAddress,
        uint256 tokenId,
        string calldata agentURI,
        IERC8004IdentityRegistry.MetadataEntry[] memory metadata
    ) external returns (uint256 agentId);

    /// @notice Convenience overload equivalent to `register(...)` with an empty metadata array.
    function register(IERC8217.Standard standard, address boundAddress, uint256 tokenId, string calldata agentURI)
        external
        returns (uint256 agentId);
}

